import{j as e}from"./framer-CnDHW2dc.js";import{d as r}from"./index-CD7lj_N0.js";const n=[{slug:"hazari-three-card-hand-odds",title:"How Rare Is a Troy? The Odds of Every Three-Card Hand in Hazari",summary:"Exact odds for Troy, Colour Run, Run, Colour, Pair and Indi in Hazari, counted across all 22,100 three-card hands, plus a surprise about which is rarer.",date:"2026-11-24",tags:["Hazari","Card Games","Probability","Odds"],hub:"hazari",topic:"Odds and numbers",blocks:[{t:"p",text:"In Hazari every group of cards is judged as a three-card hand. The order, from strongest to weakest, is Troy, Colour Run, Run, Colour, Pair and Indi. Knowing the order is easy. Knowing how rare each hand is tells you how much to trust a group when you arrange your cards."},{t:"p",text:"I counted them. There are 22,100 different ways to pick three cards from a 52-card deck, and I ran every one of them through the same function the game engine uses to rank hands."},{t:"h2",text:"The numbers"},{t:"ul",items:["**Troy** (three cards of one rank): 52 hands, 0.235%, about 1 in 425.","**Colour Run** (a sequence in one suit): 48 hands, 0.217%, about 1 in 460.","**Run** (a sequence in mixed suits): 720 hands, 3.258%, about 1 in 31.","**Colour** (one suit, no sequence): 1,096 hands, 4.959%, about 1 in 20.","**Pair** (two cards of one rank): 3,744 hands, 16.941%, about 1 in 6.","**Indi** (none of the above): 16,440 hands, 74.389%, about three in four."]},{t:"p",text:"The six counts add up to 22,100, which is a useful check on the counting."},{t:"h2",text:"A surprise: Colour Run is rarer than Troy"},{t:"p",text:"Hazari ranks a Troy above a Colour Run, but there are only 48 Colour Runs against 52 Troys. In a random three-card hand a Colour Run is slightly harder to get. The ranking is a convention of the game, not a ranking by rarity, so do not be surprised when a table argues about it."},{t:"p",text:"The same counts appear in three-card poker, which uses the same six hands. That agreement is a good independent check that the counting is right."},{t:"h2",text:"What the odds mean for a group"},{t:"p",text:"Rank a hand by how many other three-card hands it beats and the picture becomes clearer:"},{t:"ul",items:["A **Pair** beats every Indi, so it already beats about three hands in four.","A **Colour** beats about 91% of all hands.","A **Run** beats about 96%.","A **Troy** or **Colour Run** beats more than 99%."]},{t:"p",text:"These figures are the reason a plain Pair is a respectable group, and why the computer opponent in the scorekeeper treats the jump from Indi to Pair as worth far more than the jump from Run to Colour Run. The [article on how the computer chooses its cards](/blog/how-the-hazari-computer-opponent-works/) uses exactly this idea."},{t:"h2",text:"A limit of these numbers"},{t:"p",text:"These are odds for three random cards. In the real game you hold 13 cards and choose how to group them, so you can build a Pair or a Colour far more often than random chance suggests. The [number of ways to arrange 13 cards](/blog/ways-to-arrange-13-cards-hazari/) shows how much choice you actually have."},{t:"p",text:"Rank order and tie-breaks follow the standard rules in the [Hazari rules guide](https://hazari-card-game-scoring.vercel.app/hazari-game-rules). Check your own table's variations before you rely on a close call."}]},{slug:"why-hazari-deal-is-360-points",title:"Why Every Hazari Deal Is Worth Exactly 360 Points",summary:"The arithmetic behind 360 points per deal, how it splits across the four rounds, and the one-line check that catches most Hazari scoring mistakes.",date:"2026-11-24",tags:["Hazari","Card Games","Scoring","Arithmetic"],hub:"hazari",topic:"Odds and numbers",blocks:[{t:"p",text:"Every deal of standard Hazari hands out exactly 360 points, no more and no less. That fixed total is the most useful fact in the scoring, because it lets you catch mistakes in seconds. Here is where it comes from."},{t:"h2",text:"The arithmetic"},{t:"ul",items:["In each suit, the ace, king, queen, jack and ten are worth 10 points each. That is five cards and 50 points.","The 2 through the 9 are worth 5 points each. That is eight cards and 40 points.","One suit is worth 50 + 40 = 90 points.","Four suits are worth 4 × 90 = **360 points**."]},{t:"p",text:"Put another way, 20 cards are worth 10 points (200 points) and 32 cards are worth 5 points (160 points). The full table is in the [Hazari card points guide](https://hazari-card-game-scoring.vercel.app/hazari-card-points)."},{t:"h2",text:"How the 360 points reach players"},{t:"p",text:"Each player arranges 13 cards into groups of 3, 3, 3 and 4. The groups are compared one round at a time, and the winner of a round takes every card played in it. The first three rounds each contain 12 cards (four players, three cards each). The last round contains 16 cards because each player puts down four."},{t:"p",text:"The average card is worth 360 ÷ 52, a little under 7 points. So on average:"},{t:"ul",items:["A 12-card round holds about **83 points**.","The 16-card round holds about **111 points**, nearly a third of the whole deal."]},{t:"p",text:"A real round can hold more or fewer points than the average, depending on which cards were played. The point is that the last round is the biggest prize, which is why the [four-card group](/blog/hazari-four-card-group/) deserves more thought than its position suggests."},{t:"h2",text:"The one-line check"},{t:"p",text:"After each deal, add up the points every player collected. The answer must be 360. If it is not, someone miscounted, and you know it before the totals are written down."},{t:"p",text:"If three players have 275 between them, the fourth must have 85. If the scores add up to 350, ten points went missing. A common slip is counting a ten as 5 points or a 9 as 10."},{t:"p",text:"The scorekeeper uses this check. When a round does not add up to the round total, it asks you to confirm before saving instead of silently accepting it. It does not block you, because some tables play with different totals."},{t:"h2",text:"When 360 is not the total"},{t:"p",text:"Some tables use other point values or totals. The [house rules checklist](/blog/hazari-house-rules-checklist/) lists what to agree on before the first deal. If you change the card values, change the expected total with them."},{t:"p",text:"Want to see a full game of these deals added up? The [worked scoring example](/blog/hazari-scoring-worked-example/) follows one game to 1,000."}]},{slug:"how-many-deals-in-a-game-of-hazari",title:"How Many Deals Does a Game of Hazari to 1,000 Take?",summary:"I simulated 400 whole Hazari games to find out. The average is about eight deals, the shortest possible is three, and the results show why skill shortens games.",date:"2026-11-24",tags:["Hazari","Card Games","Simulation","Game Length"],hub:"hazari",topic:"Odds and numbers",blocks:[{t:"p",text:"You are about to start a game of Hazari to 1,000. How long will it last? Players guess anything from a handful of deals to an evening that never ends. I simulated 400 complete games to get a number."},{t:"h2",text:"How I tested it"},{t:"p",text:"Four computer players played each game under the standard rules: 13 cards each, groups of 3, 3, 3 and 4, scores carried from deal to deal, and the game ending when someone reaches 1,000. In this first test every player arranged their cards at random, within the rules. That makes it a floor for skill, not a picture of how people play."},{t:"p",text:"The simulation also assumes the deal passes to the next player each time and the player after the dealer leads the first round. If your table differs, the exact numbers will shift a little."},{t:"h2",text:"What came out"},{t:"ul",items:["**Average:** 7.9 deals per game.","**Middle game:** 8 deals.","**Shortest:** 3 deals. **Longest:** 11 deals.","**Typical range:** 8 games in 10 lasted between 6 and 10 deals."]},{t:"p",text:"The minimum of three deals is not luck. One deal is worth 360 points, so two deals can give a player at most 720. Reaching 1,000 needs at least three, and that needs a near-perfect run."},{t:"h2",text:"Does the seat matter?"},{t:"p",text:"Across the 400 games the four seats won 95, 92, 107 and 106 times. That is close to an even split of 100 each, so I found no sign that sitting first or last helps. Two games ended with two players tied for the top score."},{t:"h2",text:"Skill shortens the game"},{t:"p",text:"Strong arrangement ends games faster, because one player keeps winning rounds and the points pile up in one place."},{t:"ul",items:["One player choosing the best of 40 random arrangements against three random players won all 200 simulated games, in about 4.3 deals on average.","One player using an exhaustive search for the best arrangement, against the same three random players, won all 60 simulated games, in about 3.3 deals on average."]},{t:"p",text:"So if a game drags on, a likely reason is that nobody is arranging much better than anyone else. A table of evenly matched players trades points around for longer."},{t:"h2",text:"Planning an evening"},{t:"p",text:"Plan for around eight deals, and be ready for six or ten. Time one deal at your table and multiply. If you want a shorter game, a lower target is easy to agree on; the [house rules checklist](/blog/hazari-house-rules-checklist/) covers it."},{t:"p",text:"Scores add up fast, so keeping them in one place matters. See the [full game worked example](/blog/hazari-scoring-worked-example/) for how the totals build up."}]},{slug:"ways-to-arrange-13-cards-hazari",title:"200,200 Ways to Arrange 13 Cards: Why Hazari Is Harder Than It Looks",summary:"A 13-card Hazari hand can be split into groups in 200,200 ways. About a tenth are legal. Here is the counting, and why arranging is the real skill.",date:"2026-11-24",tags:["Hazari","Card Games","Combinatorics","Strategy"],hub:"hazari",topic:"Odds and numbers",blocks:[{t:"p",text:"In Hazari nobody plays a card from the hand one by one. You arrange all 13 cards into groups before the first round begins, and the arrangement is hidden until the groups are compared. Everything depends on that one decision, so it is worth knowing how large the decision is."},{t:"h2",text:"Counting the splits"},{t:"p",text:"The groups are three, three, three and four cards. To count the ways to split 13 cards:"},{t:"ol",items:["Choose the four cards for the last group: 13 choose 4, which is **715** ways.","Split the other nine cards into three groups of three. The order of those groups does not matter yet, which gives **280** ways.","Multiply: 715 × 280 = **200,200** different splits."]},{t:"p",text:"That is the number of ways to divide any 13-card hand. It is a little over two hundred thousand."},{t:"h2",text:"Most of them are not allowed"},{t:"p",text:"The rules say the groups must go from strongest to weakest, with the four-card group last and the weakest of all. The four-card group is judged by its best three cards. A split where the four-card group beats any of the other groups is illegal."},{t:"p",text:"I counted the legal splits for twelve random hands. The numbers ranged from 14,153 to 25,622, and the average was about 20,650. So roughly one split in ten is legal."},{t:"p",text:"Once a split is legal, the strongest-first order is settled, because you simply sort the three groups of three by strength."},{t:"h2",text:"What that means for a player"},{t:"ul",items:["Nobody can check 20,000 arrangements by eye, so human arranging is a matter of principles and pattern spotting.","A computer can check them all. The scorekeeper's hardest computer opponent does exactly that.","The choice matters a great deal. In simulation, a player who picked the best arrangement beat three players who arranged at random in every game I ran."]},{t:"p",text:"You do not need to count to play well. A few principles remove most of the choices, and the [practical guide to arranging your cards](/blog/how-to-arrange-cards-in-hazari/) lists them."},{t:"p",text:"To see what a computer does with all of them, read [how the Hazari computer opponent chooses its cards](/blog/how-the-hazari-computer-opponent-works/). To see how strong a single group is, check the [odds of every three-card hand](/blog/hazari-three-card-hand-odds/)."},{t:"p",text:"For the rules that decide which splits are legal, see the [Hazari rules guide](https://hazari-card-game-scoring.vercel.app/hazari-game-rules)."}]}],i=[{slug:"how-to-arrange-cards-in-hazari",title:"How to Arrange Your Cards in Hazari: A Practical Guide to 3-3-3-4",summary:"Six practical principles for splitting 13 Hazari cards into groups, backed by what a full search chooses across 400 random hands.",date:"2026-11-24",tags:["Hazari","Card Games","Strategy","Arranging Cards"],hub:"hazari",topic:"Strategy",blocks:[{t:"p",text:"Hazari is decided before the first round. You have 13 cards, you must split them into groups of 3, 3, 3 and 4, and the groups must run from strongest to weakest with the four-card group the weakest of all. There are [about 200,000 ways to split a hand](/blog/ways-to-arrange-13-cards-hazari/), roughly a tenth of them legal."},{t:"p",text:"These principles cut that down to a handful. To check them, I had the game engine search every legal split of 400 random hands and looked at what the best ones have in common."},{t:"h2",text:"1. Aim for no weak groups"},{t:"p",text:"The weakest hand in Hazari is an Indi, a group with no pair, colour or run. In a random arrangement most groups are Indi: across 1,000 random legal arrangements, only about 1.2 of the four groups were a Pair or better on average."},{t:"p",text:"In the best arrangement the search found, all four groups were a Pair or better in every one of the 400 hands. Making sure no group is a plain Indi is the single biggest gain available."},{t:"h2",text:"2. Lift your weakest group before you polish your strongest"},{t:"p",text:"Going from Indi to Pair is a huge step: a Pair beats about three hands in four. Going from a Run to a Colour Run barely matters, as both already beat most hands. [The odds of each three-card hand](/blog/hazari-three-card-hand-odds/) show the returns shrink as hands get stronger. Spend cards where they raise a weak group first."},{t:"h2",text:"3. Do not automatically use a Troy"},{t:"p",text:"A Troy is the strongest group. It also uses three cards of one rank, which may be the cards you needed for a run or a pair elsewhere. In the searched arrangements, the first group was a Troy in about 29% of hands, a Colour Run in about 20% and a Run in about 50%. Holding three of a kind does not always mean using it as a Troy, because spreading those cards around can lift weaker groups instead."},{t:"h2",text:"4. Use the fourth card of the last group as your dump"},{t:"p",text:"The four-card group is judged by its best three cards. The fourth card does not weaken it, so put your awkward card there, the one that fits nowhere else. See [the four-card group in detail](/blog/hazari-four-card-group/)."},{t:"h2",text:"5. Get the ace right"},{t:"p",text:"An ace is high in A-K-Q, which is the highest run, and low in A-2-3, which is the second highest. A run like 2-A-K does not count. A sequence of three cards that wraps around the ace is not a run, so do not build one."},{t:"h2",text:"6. Check the order before you reveal"},{t:"p",text:"Read your groups from first to last and ask: is each one at least as strong as the next? Is the four-card group the weakest, judging it by its best three cards? A wrong order is the most common reason for an invalid arrangement. The [list of beginner mistakes](/blog/hazari-beginner-mistakes/) has more."},{t:"h2",text:"What the best arrangements look like"},{t:"ul",items:["**Group 1:** a Troy, Colour Run or Run in almost every hand.","**Group 2:** a Run in about 7 hands in 10, and a Colour in about 2 in 10.","**Group 3:** a Colour in about two thirds of hands, a Run in about one third.","**Group 4:** a Colour in about four hands in five, and a Pair in about one in six."]},{t:"p",text:"That is a model, not a promise. It values a group by how many random three-card hands it beats, and it treats opponents as unknown. Real players are not random, so use these as a starting point and adjust when you know how your table plays."},{t:"note",text:"You can test your own arrangements against computer players in the free scorekeeper, which also checks that your order is legal before you press Up!"}]},{slug:"hazari-four-card-group",title:"The Four-Card Group in Hazari: Weakest by Rule, Biggest Prize in the Deal",summary:"The last Hazari group has four cards, must be your weakest, and still carries about 31% of the deal's points. Here is how to use it well.",date:"2026-11-24",tags:["Hazari","Card Games","Strategy","Scoring"],hub:"hazari",topic:"Strategy",blocks:[{t:"p",text:"Hazari has an odd rule. Your last group has four cards, not three, and it has to be the weakest of the four. Yet it is the group that can win the biggest pile of cards in the deal."},{t:"h2",text:"How a four-card group is judged"},{t:"p",text:"A four-card group is compared by its best three cards, using the same order of Troy, Colour Run, Run, Colour, Pair and Indi. The fourth card does not strengthen the group, and it does not weaken it. It just comes along for the ride."},{t:"p",text:"The group must also not be stronger than any of your other three groups. If it is, your arrangement is out of order."},{t:"h2",text:"Why it matters more than it looks"},{t:"p",text:"Rounds one to three each contain 12 cards, because four players put down three cards each. The last round contains 16 cards, because each player puts down four. That is 16 of the 52 cards, about 31% of the deal. On average the four-card round holds about 111 points, against about 83 in each earlier round."},{t:"p",text:"So you are dealing with a weaker group and a bigger prize. If your opponents' fourth groups are also weak, a Pair or a Colour in this spot can win a lot of points. The [arithmetic of the 360-point deal](/blog/why-hazari-deal-is-360-points/) explains where those averages come from."},{t:"h2",text:"What a careful search chooses"},{t:"p",text:"Across 400 random hands, the best arrangement found by exhaustive search never left the four-card group as an Indi. It was:"},{t:"ul",items:["a **Colour** in about 79% of hands,","a **Pair** in about 16% of hands,","a **Run** in about 4%,","a Colour Run in a fraction of a percent."]},{t:"p",text:"When the cards allow it, the search prefers a decent four-card group over a slightly stronger first group, because the fourth round is worth more than the others."},{t:"h2",text:"A simple way to build it"},{t:"ol",items:["Arrange the other nine cards into the three best groups of three you can.","Look at the four cards left. Do any three of them make a Pair, Colour or Run?","If not, swap a card between groups until the four-card group improves without making one of the others weaker than it.","Check the order once more. Your fourth group must not beat your third."]},{t:"h2",text:"A real example"},{t:"p",text:"In the [worked deal](/blog/hazari-worked-deal-example/), a Pair of Queens in the four-card group won the last round and 125 points, more than the first three rounds put together for that player."},{t:"p",text:"Rules differ by region on what happens when two groups are equal. Agree on that first, as the [house rules checklist](/blog/hazari-house-rules-checklist/) suggests."}]},{slug:"hazari-beginner-mistakes",title:"7 Mistakes New Hazari Players Make When Arranging Cards",summary:"Seven common errors when arranging Hazari cards, from putting the groups in the wrong order to getting the ace wrong, with how to avoid each.",date:"2026-11-24",tags:["Hazari","Card Games","Beginners","Rules"],hub:"hazari",topic:"Strategy",blocks:[{t:"p",text:"Hazari rules are simple to state and easy to slip on. These are the seven mistakes that cost new players rounds, or cause an argument at the reveal."},{t:"h2",text:"1. Putting the groups in the wrong order"},{t:"p",text:"The groups must run from strongest to weakest. If your third group is stronger than your second, the arrangement is not legal. Read your groups from left to right before you reveal."},{t:"h2",text:"2. Making the four-card group too strong"},{t:"p",text:"The four-card group has to be the weakest of the four. Find its best three cards and compare them with your third group. If the four-card group wins that comparison, move cards around."},{t:"h2",text:"3. Thinking all four cards count"},{t:"p",text:"The four-card group is judged by its best three cards. The fourth card is a spare. It is a handy place for a card that fits nowhere else, and it can make the last pile contain more points without changing the strength."},{t:"h2",text:"4. Getting the ace wrong"},{t:"p",text:"An ace is high in A-K-Q, the highest run, and low in A-2-3, the second highest. A hand such as 2-A-K is not a run, because the sequence does not wrap around the ace."},{t:"h2",text:"5. Mixing up Colour and Run"},{t:"ul",items:["A **Colour** is three cards of one suit that are not in sequence.","A **Run** is three cards in sequence, in mixed suits.","A **Colour Run** is both: a sequence in one suit, and it beats a plain Run."]},{t:"p",text:"A Colour is weaker than a Run, which surprises people who play poker, where a flush beats a straight in many versions."},{t:"h2",text:"6. Putting everything into one group"},{t:"p",text:"A monster first group with three Indi groups behind it looks strong and usually isn't. In 1,000 random legal arrangements, only 1.7% had all four groups at Pair or better, while a careful search reached that in every hand tested. Spread your strength: [see why](/blog/how-to-arrange-cards-in-hazari/)."},{t:"h2",text:"7. Counting the points wrongly"},{t:"p",text:"The ace, king, queen, jack and ten are worth 10 points each. The 2 through the 9 are worth 5 each. A round winner takes every card in that round, not just their own. After the deal, all points collected must total 360. If they do not, recount. The [360-point check](/blog/why-hazari-deal-is-360-points/) explains the rule."},{t:"h2",text:"Settle the rest before you play"},{t:"p",text:"Direction of play, who leads, and what happens when two groups tie differ between tables. Agree on them before the first deal. The [house rules checklist](/blog/hazari-house-rules-checklist/) lists them all, and the [Hazari rules guide](https://hazari-card-game-scoring.vercel.app/hazari-game-rules) has the standard version."}]},{slug:"hazari-worked-deal-example",title:"One Hazari Deal, Round by Round: A Worked Example with Real Cards",summary:"A full four-player Hazari deal with every hand, every group and every round shown, so you can see how groups are compared and how 360 points get split.",date:"2026-11-24",tags:["Hazari","Card Games","Worked Example","Beginners"],hub:"hazari",topic:"Strategy",blocks:[{t:"p",text:"The easiest way to learn Hazari is to watch a deal played through. I generated this one with the game engine, using four medium-strength computer players, and checked that the points add up to 360."},{t:"h2",text:"The four arrangements"},{t:"p",text:"Each player's 13 cards, split into groups of 3, 3, 3 and 4, strongest first:"},{t:"ul",items:["**Player 1:** J♦ 10♣ 9♦ (Run) · 10♠ 6♠ 2♠ (Colour) · K♥ K♦ 8♦ (Pair) · Q♠ Q♣ J♣ 4♥ (Pair of Queens)","**Player 2:** A♦ Q♦ 5♦ (Colour) · K♣ 7♦ 7♣ (Pair) · 9♠ 4♠ 4♣ (Pair) · 10♥ 5♣ 3♠ 3♥ (Pair of 3s)","**Player 3:** K♠ 8♠ 7♠ (Colour) · 8♣ 6♣ 2♣ (Colour) · 7♥ 6♥ 2♥ (Colour) · A♠ J♠ J♥ 9♣ (Pair of Jacks)","**Player 4:** A♥ 8♥ 5♥ (Colour) · 10♦ 6♦ 4♦ (Colour) · 9♥ 3♦ 3♣ (Pair) · A♣ Q♥ 5♠ 2♦ (Indi)"]},{t:"p",text:"Check one: Player 4's last group is A♣ Q♥ 5♠ 2♦. Its best three cards are A, Q and 5, an Indi, and it is the weakest group in that hand, so the arrangement is legal. Play goes in order from Player 2, who leads the first round in this simulation."},{t:"h2",text:"Round 1: a Run beats three Colours"},{t:"p",text:"Players compare their first groups. Players 2, 3 and 4 all show a Colour, but Player 1 shows a Run (J-10-9), and a Run beats a Colour. Player 1 wins all 12 cards, worth **90 points**."},{t:"h2",text:"Round 2: the higher Colour wins"},{t:"p",text:"Three players show a Colour. Player 4's 10-6-4 of diamonds beats Player 1's 10-6-2 of spades, because the first two cards tie and the 4 is higher than the 2. Player 2's Pair loses to any Colour. Player 4 wins **75 points**."},{t:"h2",text:"Round 3: one Colour among Pairs"},{t:"p",text:"Player 3's Colour (7-6-2 of hearts) beats three Pairs, the Kings of Player 1, the 4s of Player 2 and the 3s of Player 4. Player 3 wins **70 points**."},{t:"h2",text:"Round 4: the big pile"},{t:"p",text:"Everyone shows four cards, and the best three decide. Player 1 has a Pair of Queens, Player 3 a Pair of Jacks, Player 2 a Pair of 3s, and Player 4 has no Pair. Queens win. This round holds 16 cards, so Player 1 collects **125 points**."},{t:"h2",text:"The result"},{t:"ul",items:["Player 1: 90 + 125 = **215**","Player 4: **75**","Player 3: **70**","Player 2: **0**"]},{t:"p",text:"215 + 75 + 70 + 0 = 360, as it must. Player 2 had a respectable hand and still won nothing: a Pair or a Colour was always beaten by something stronger in the same round."},{t:"h2",text:"What to take from it"},{t:"ul",items:["Rounds are won by comparing groups in the same position, not by comparing whole hands.","A single Run or Colour in the right position can win a whole round.","The four-card group decided the biggest pile, as the [article on the four-card group](/blog/hazari-four-card-group/) describes."]},{t:"p",text:"The next step is to add these deal totals to a running score. The [scoring example](/blog/hazari-scoring-worked-example/) follows a full game to 1,000."}]}],h=[{slug:"hazari-scoring-worked-example",title:"Scoring Hazari Round by Round: One Full Game to 1,000, Worked Through",summary:"A complete eight-deal Hazari game added up deal by deal, with every running total, so you can see how scores build and how the game ends.",date:"2026-11-24",tags:["Hazari","Card Games","Scoring","Worked Example"],hub:"hazari",topic:"Scoring and house rules",blocks:[{t:"p",text:"Hazari scores are easy to understand and easy to get wrong over an evening. This is one complete game, every deal added up, so you can follow the numbers from the first deal to the winning total."},{t:"p",text:"I generated the game with the Hazari engine, with four computer players. Each deal's points are what each player collected, and every deal adds up to 360."},{t:"h2",text:"The game, deal by deal"},{t:"p",text:"Each line shows the points collected in that deal, then the running totals for Players A, B, C and D."},{t:"ol",items:["**Deal 1:** 185, 0, 0, 175. Totals: **185, 0, 0, 175**.","**Deal 2:** 270, 90, 0, 0. Totals: **455, 90, 0, 175**.","**Deal 3:** 0, 0, 265, 95. Totals: **455, 90, 265, 270**.","**Deal 4:** 280, 0, 80, 0. Totals: **735, 90, 345, 270**.","**Deal 5:** 0, 80, 85, 195. Totals: **735, 170, 430, 465**.","**Deal 6:** 180, 0, 90, 90. Totals: **915, 170, 520, 555**.","**Deal 7:** 0, 0, 85, 275. Totals: **915, 170, 605, 830**.","**Deal 8:** 175, 0, 185, 0. Totals: **1,090, 170, 790, 830**."]},{t:"p",text:"Player A reached 1,090 in Deal 8 and won. Notice what happened along the way."},{t:"h2",text:"What the numbers show"},{t:"ul",items:["**Every row adds up to 360.** Deal 5, for example, is 0 + 80 + 85 + 195 = 360. If a row does not, someone miscounted.","**Points come in lumps.** A round winner takes every card in the round, so a player often collects 0 or 85 or 270 and rarely a number in between.","**The leader can lose it.** After Deal 6, Player A was on 915 and Player D on 555. After Deal 7 Player D had 830, and Player A, who scored nothing in Deal 7, still led by 85.","**You can finish above 1,000.** Player A won with 1,090 because the last deal added 175, not just the 85 needed."]},{t:"h2",text:"What if two players pass 1,000 together?"},{t:"p",text:"Two players can pass the target in the same deal. The usual way to settle it is that the higher total wins. Agree on this before you play, because tables differ. The [house rules checklist](/blog/hazari-house-rules-checklist/) covers it."},{t:"h2",text:"Keeping the running score"},{t:"ol",items:["After each deal, write each player's points on one row.","Add the row. It must be 360.","Add each player's points to their previous total, in a separate row, and check that the totals add up to 360 times the number of deals. After Deal 8 the totals add to 2,880.","Stop when a total reaches 1,000."]},{t:"p",text:"That last check is a good one. In this game the four totals after eight deals are 1,090 + 170 + 790 + 830 = 2,880, which is 8 × 360, so nothing went missing along the way."},{t:"p",text:"For the arithmetic behind each row, see [why every deal is worth 360 points](/blog/why-hazari-deal-is-360-points/). If your own totals ever disagree, [settle the argument in two minutes](/blog/settle-hazari-scoring-disputes/). And to know how long a game like this should take, read [how many deals a game to 1,000 lasts](/blog/how-many-deals-in-a-game-of-hazari/)."},{t:"p",text:"The scorekeeper does these additions for you and flags a round that does not add up. The [guide to scoring Hazari](https://hazari-card-game-scoring.vercel.app/how-to-score-hazari) walks through it screen by screen."}]},{slug:"settle-hazari-scoring-disputes",title:"How to Settle a Hazari Scoring Argument in Two Minutes",summary:"A five-step method to find a Hazari scoring mistake fast, using the 360-point check, instead of arguing about who remembers what.",date:"2026-11-24",tags:["Hazari","Card Games","Scoring","Arguments"],hub:"hazari",topic:"Scoring and house rules",blocks:[{t:"p",text:"Somebody says the totals are wrong. Somebody else is sure they added that round twice. Sound familiar? You can settle almost any Hazari scoring argument in a couple of minutes if you use the one fact that never changes: every deal is worth exactly 360 points."},{t:"h2",text:"Step 1: check each deal adds up to 360"},{t:"p",text:"Go down the score sheet row by row. Add the points of the four players in each deal. Every row must come to 360. The first row that does not is where the problem is."},{t:"h2",text:"Step 2: if every row adds up, check the running totals"},{t:"p",text:"A good check: the four running totals together must equal 360 times the number of deals played. After five deals they must add to 1,800. If they do not, an addition went wrong, and you can find it by re-adding one player's column at a time."},{t:"h2",text:"Step 3: if a row is wrong, rebuild it from the rounds"},{t:"p",text:"Each round's winner takes every card played. The first three rounds hold 12 cards each, and the last holds 16. Ask who won each of the four rounds and add up the card points in that round: 10 for ace, king, queen, jack and ten, 5 for anything else. This usually turns up the slip: a card counted at the wrong value, or a round credited to the wrong player."},{t:"h2",text:"Step 4: agree one scorer"},{t:"p",text:"A lot of arguments start because two people keep score. Pick one scorekeeper for the whole game and make that person's record the official one. Others can check it, but they do not keep a rival version."},{t:"h2",text:"Step 5: when memory fails, go back to the rule"},{t:"p",text:"If nobody can reconstruct the round, fall back on what you agreed before the game. This is the reason to agree on the rules at the start, such as what happens when two groups tie. See the [house rules checklist](/blog/hazari-house-rules-checklist/)."},{t:"h2",text:"Make mistakes harder to make"},{t:"ul",items:["Write each deal on its own row, not as a running number.","Say each player's points out loud as you write them.","Do the 360 check before you move on to the next deal.","Keep the full history, so a bad row can be found later."]},{t:"p",text:"A scorekeeper app can do the 360 check and keep every row for you. The [scoring guide](https://hazari-card-game-scoring.vercel.app/how-to-score-hazari) shows how. Or read the [arithmetic behind the 360 points](/blog/why-hazari-deal-is-360-points/) first."}]},{slug:"hazari-house-rules-checklist",title:"Hazari House Rules Checklist: Agree These 8 Things Before the First Deal",summary:"Hazari rules vary by region and by family. Eight things to agree on before you play, so the first argument never happens.",date:"2026-11-24",tags:["Hazari","Card Games","House Rules","Rules"],hub:"hazari",topic:"Scoring and house rules",blocks:[{t:"p",text:"Ask three Hazari players about the rules and you may hear three versions. Regional variants exist, and families often add their own. The standard four-player rules are a good base, but the arguments tend to start in the gaps. Agree on these eight things before the first deal."},{t:"h2",text:"The checklist"},{t:"ol",items:["**The target score.** The usual target is 1,000. Pick a lower number, such as 500, for a shorter game.","**The points in a deal.** With the standard card values (10 for ace, king, queen, jack and ten; 5 for the rest) a deal is worth 360. If you change a card value, change the total you expect.","**Direction of play.** Standard Hazari goes counter-clockwise. Make sure everyone agrees on who goes after whom.","**Who leads.** Agree who plays first in the first round, and who leads after that.","**Equal groups.** When two groups tie in the same round, the standard rule is that the group played last wins. Some tables decide it differently. Agree on one.","**The ace.** An ace counts high in A-K-Q and low in A-2-3. Confirm that 2-A-K does not count as a run.","**Two players pass the target together.** The usual answer is that the higher total wins. Say so out loud.","**Who keeps score.** Name one scorekeeper and agree how mistakes are corrected."]},{t:"h2",text:"Why a short list works"},{t:"p",text:"Most disputes are not about the main rules. They are about the edge cases: a tie, a deal that goes wrong, a total that no one can reconstruct. A minute spent on this list is a lot cheaper than ten minutes of arguing mid-game."},{t:"h2",text:"Where the standard rules come from"},{t:"p",text:"The standard rules follow the description on [Pagat](https://www.pagat.com/partition/hazari.html), a long-running reference for card games, which also notes regional differences. The scorekeeper uses those rules as its defaults, with an adjustable target and round total, because tables differ."},{t:"p",text:"The [Hazari rules guide](https://hazari-card-game-scoring.vercel.app/hazari-game-rules) and the [card points guide](https://hazari-card-game-scoring.vercel.app/hazari-card-points) cover the standard version in more detail."},{t:"p",text:"Once the rules are agreed, keep the score in one place. [Paper or an app?](/blog/paper-or-app-hazari-scorekeeping/) compares the options, and [one full game worked through](/blog/hazari-scoring-worked-example/) shows how the totals build up."},{t:"note",text:"If your family plays differently, your rules are the right rules. The point of the list is only to make sure everyone at the table is playing the same ones."}]},{slug:"paper-or-app-hazari-scorekeeping",title:"Paper or App? How to Keep Hazari Score Without Arguments",summary:"An honest comparison of keeping Hazari score on paper, in a notes app and in a scorekeeper, with a simple paper layout that makes errors visible.",date:"2026-11-24",tags:["Hazari","Card Games","Scoring","Scorekeeper"],hub:"hazari",topic:"Scoring and house rules",blocks:[{t:"p",text:"Paper has run Hazari games for generations. A phone is in everyone's pocket now. Which keeps the better score? It depends on what you value, and both can go wrong in predictable ways."},{t:"h2",text:"Paper"},{t:"ul",items:["**Strengths:** free, needs no battery, everyone can see it at once and nothing can freeze.","**Weaknesses:** crossing out is messy, and running totals have to be added by hand. A single slip carries into every later row."]},{t:"h2",text:"A phone notes app"},{t:"ul",items:["**Strengths:** easy to share, easy to edit.","**Weaknesses:** you have to type the whole running total every time, and it is easy to overwrite the wrong number."]},{t:"h2",text:"A scorekeeper app"},{t:"ul",items:["**Strengths:** adds the totals itself, ranks the players, checks that a round adds up, keeps every round so a mistake can be found, and can share a live view.","**Weaknesses:** it needs a phone, and one person must be trusted to enter the scores."]},{t:"h2",text:"A paper layout that makes mistakes visible"},{t:"p",text:"If you stay with paper, use this layout:"},{t:"ol",items:["One column per player and one row per deal.","A last column on the right for the row check, where you add the four points and write 360.","A separate block for running totals, so you never overwrite a points row.","A single line under the totals showing 360 times the number of deals, to compare with the total of the four running scores."]},{t:"p",text:"Those two checks, the row sum and the grand total, catch nearly every addition error. The [article on settling scoring arguments](/blog/settle-hazari-scoring-disputes/) shows how to use them."},{t:"h2",text:"When an app is worth it"},{t:"p",text:"A scorekeeper helps most when you play long games, when the table argues, or when people who are not at the table want to follow along. If you only play a short game with four people sitting around one sheet of paper, paper is fine."},{t:"p",text:"I built a free scorekeeper for the other case. It works offline, is in English and Bangla, and the [story of how it works](/blog/hazari-scoring-app/) is on this site."}]},{slug:"hazari-banter-and-funny-tags",title:"Roasting Your Friends at the Hazari Table: Funny Leaderboard Tags",summary:"Hazari is a game of banter. How funny leaderboard tags work, example lines in English and Bangla, and how to roast without hurting anyone.",date:"2026-11-24",tags:["Hazari","Card Games","Banter","Bangla"],hub:"hazari",topic:"Playing with friends",blocks:[{t:"p",text:"A good Hazari night is half cards and half teasing. Whoever leads gets a boast, whoever trails gets a roast, and everyone laughs. I built that into the scorekeeper's leaderboard, so here is how it works, with a few lines you can steal."},{t:"h2",text:"How the tags work"},{t:"ul",items:["Each player gets a short tag based on where they stand on the leaderboard: first, second, third or last.","Tags only appear once two rounds have been saved, so the early scores are not teased.","The tag stays the same until the next round is saved, so it does not flicker while you look at it.","Bangla players get Bangla tags and English players get English ones, so the joke lands in the language you play in."]},{t:"h2",text:"A few English examples"},{t:"ul",items:["**First place:** “Boss mode”, “Main character”, “Chef mode: cooked everyone”.","**Second place:** “Breathing down their neck”, “Silver medal, smiling anyway”, “Eternal runner-up”.","**Third place:** “Mid and proud”, “Stuck in traffic”, “Background dancer energy”.","**Last place:** “Donating points”, “Cards hate me today”."]},{t:"h2",text:"And in Bangla"},{t:"ul",items:["**প্রথম:** “রাজা এসে গেছে, বস মোড অন”।","**দ্বিতীয়:** “ঘাড়ের কাছে নিঃশ্বাস”।","**শেষ:** “দান-খয়রাত চলছে…”।"]},{t:"h2",text:"How to roast kindly"},{t:"ol",items:["**Tease the position, not the person.** “Donating points” is about the score. Jokes about someone's looks, family or background are not.","**Share the loser's seat.** Everybody ends up last at some point, so the same joke is aimed at the whole table over an evening.","**Keep it short.** A good tease is one line.","**Stop when someone is not laughing.** If a joke lands badly, drop it."]},{t:"p",text:"The tags are playful by design, and they are for friends who already like each other. If your table prefers a quieter game, play without showing the leaderboard."},{t:"p",text:"Tags suit a long game, because they only appear after two rounds and change with every saved round. See [how many deals to expect](/blog/how-many-deals-in-a-game-of-hazari/). For the Bangla side of the app, read about [the card names and how Bangla is handled](/blog/bangla-card-names-hazari-app/)."},{t:"h2",text:"Use them"},{t:"p",text:"Keep score in the scorekeeper, and the tags appear on its leaderboard from the second round. Share the live scoreboard and your friends can watch the roasts update. The [guide to sharing a live scoreboard](/blog/share-hazari-scoreboard-live/) shows how."}]},{slug:"share-hazari-scoreboard-live",title:"Let Friends Watch Your Hazari Game Live: How to Share a Scoreboard",summary:"How to share a live, read-only Hazari scoreboard by link so friends and family who are not at the table can follow every round.",date:"2026-11-24",tags:["Hazari","Card Games","Live Scoreboard","Sharing"],hub:"hazari",topic:"Playing with friends",blocks:[{t:"p",text:"Some of the best fans of a Hazari game are not at the table. A cousin abroad, a friend who is running late, the family in the next room. A read-only live scoreboard lets them all follow the game from their own phones."},{t:"h2",text:"How to share"},{t:"ol",items:["One person at the table keeps score in the scorekeeper.","Open the game, choose **Share live scoreboard**, then **Start sharing**.","Send the link, or let people scan the QR code on your screen.","Everyone who opens it sees the leaderboard update as each round is saved."]},{t:"p",text:"You do not need an account to start. Sharing starts as a guest by default, and signing in with Google is optional."},{t:"h2",text:"What viewers see"},{t:"ul",items:["The ranked leaderboard, with who is leading and who deals next.","A table of the rounds so far.","Small highlights, such as a winning streak, and the funny tags that go with the standings."]},{t:"p",text:"Viewers cannot change a score, and they do not see the scorer's drafts, other games or sign-in details. The scorer's phone stays the single source of truth."},{t:"h2",text:"One link for the whole evening"},{t:"p",text:"When a game ends and you press Play again, the link stays the same, so friends keep watching without a new link. Viewers follow the current game automatically and can look back at earlier games from the same session."},{t:"h2",text:"Limits worth knowing"},{t:"ul",items:["The scorer's browser has to stay open while the game is running, because it is the scorer's phone that sends the updates.","Shared links expire on their own, and the scorer can stop sharing at any time. Stopping closes the link.","Scoring itself works without a connection. Only the live view needs the internet."]},{t:"p",text:"If you want the leaders teased while everyone watches, read about [funny leaderboard tags](/blog/hazari-banter-and-funny-tags/). If you are still deciding how to keep score, [paper or an app?](/blog/paper-or-app-hazari-scorekeeping/) compares the options."},{t:"p",text:"A short [guide to sharing a live scoreboard](https://hazari-card-game-scoring.vercel.app/share-live-scoreboard) is on the app's site, and the [design of the live scoreboard](/blog/read-only-live-scoreboard-design/) is explained here for the curious."}]},{slug:"play-hazari-against-the-computer",title:"Play Hazari Alone: Practise Against Three Computer Players",summary:"How to play Hazari on your phone against three computer opponents, with easy, medium and hard levels, auto-arrange and a scoreboard that teases you.",date:"2026-11-24",tags:["Hazari","Card Games","Single Player","Computer Opponent"],hub:"hazari",topic:"Playing with friends",blocks:[{t:"p",text:"Not everyone has three friends and a deck of cards at hand. The Hazari scorekeeper also has a single-player mode. You play against three computer players, learn how arrangements are compared and chase 1,000 points on your own."},{t:"h2",text:"How a game goes"},{t:"ol",items:["Open the game and choose **Play vs computer**. You and three computer players, Joy, Nayon and Rafi, each get 13 cards.","Arrange your cards into groups of 3, 3, 3 and 4. Tap a card, then tap an empty spot. Put your strongest group first and the four-card group last.","Press **Up!**. The four rounds are shown one at a time, with the winner and the points won.","See the deal result and the running scores, then play the next deal.","The first player to reach 1,000 wins."]},{t:"h2",text:"Three levels"},{t:"ul",items:["**Easy** (the default): the computer arranges its cards at random, within the rules.","**Medium:** it tries 40 random arrangements and keeps the best.","**Hard:** it searches every legal arrangement and keeps the best."]},{t:"p",text:"The gaps are large. In my simulations a Medium player beat three Easy players in every one of 200 games, and a Hard player did so in every one of 60. The [article on the computer opponent](/blog/how-the-hazari-computer-opponent-works/) explains how it decides."},{t:"h2",text:"Help when you are stuck"},{t:"ul",items:["**Auto-arrange** fills in the best arrangement for your hand. It is useful for learning what a strong split looks like.","**Clear** puts your cards back so you can try again.","If your groups are out of order, you are told, so you cannot reveal an illegal arrangement."]},{t:"p",text:"Try arranging yourself first, then press Auto-arrange to compare. The gap between the two is a quick lesson in strategy. The [guide to arranging cards](/blog/how-to-arrange-cards-in-hazari/) explains the principles."},{t:"h2",text:"Details"},{t:"ul",items:["Your progress is saved on your phone, so a reload does not lose the game.","It works offline, in English and in Bangla.","The leaderboard tags that tease players in a normal game appear here too, from the second deal.","It is practice, not online multiplayer. Nobody else joins, and nothing is sent anywhere."]},{t:"p",text:"The computer follows the standard rules, with a few assumptions where sources differ: the deal passes to the next player each time, and the player after the dealer leads the first round. Tables vary on both."}]}],l=[{slug:"how-the-hazari-computer-opponent-works",title:"How the Hazari Computer Opponent Chooses Its Cards",summary:"The computer in a Hazari game makes only one decision, how to arrange 13 cards. Here is how it searches 200,200 splits, scores them and plays at three levels.",date:"2026-11-24",tags:["Hazari","Game AI","TypeScript","Search","Algorithms"],hub:"hazari",topic:"Behind the app",blocks:[{t:"p",text:"Building a computer opponent for Hazari turned out to be a neat small problem. After the cards are dealt, the game contains exactly one decision: how to arrange 13 cards into groups of 3, 3, 3 and 4. Everything after that, comparing groups and awarding cards, is mechanical. So the entire intelligence of the computer is how it arranges its hand."},{t:"h2",text:"Step 1: rank every three-card hand"},{t:"p",text:"A pure function classifies three cards as Troy, Colour Run, Run, Colour, Pair or Indi, with tie-break values for comparing two hands of the same type. Aces count high in A-K-Q and low in A-2-3, and a four-card group is judged by its best three cards. This part is unit-tested against the rules, including the awkward cases such as 2-A-K not being a run."},{t:"h2",text:"Step 2: turn a hand into a score"},{t:"p",text:"The computer needs to know how good a group is. It sorts all 22,100 possible three-card hands from weakest to strongest once, and the score of a group is the share of those hands it beats, with ties counting half. A Pair scores about 0.83. A Run scores about 0.98. [The odds of each hand](/blog/hazari-three-card-hand-odds/) explain why the numbers look like that."},{t:"p",text:"An arrangement is worth the sum of its four group scores, weighted by how many cards each round holds: 12, 12, 12 and 16. The last group is weighted more because its round holds 16 cards."},{t:"h2",text:"Step 3: search"},{t:"p",text:"The hardest level checks every split. There are 715 ways to choose the four-card group and 280 ways to divide the other nine cards into three groups, which makes [200,200 splits](/blog/ways-to-arrange-13-cards-hazari/). About a tenth of them are legal, because the four-card group must not beat any of the others. The search keeps the legal split with the highest weighted score. Results for each group of cards are cached by which cards it holds, so the same group is never evaluated twice."},{t:"h2",text:"Three levels from one function"},{t:"ul",items:["**Easy:** one random legal arrangement.","**Medium:** the best of 40 random legal arrangements.","**Hard:** the best arrangement found by the full search."]},{t:"p",text:"The three levels share the scoring code and differ only in how many arrangements they look at. That also made them easy to test: the Hard level must beat the Easy level over a run of deals, and every level must always return a legal arrangement."},{t:"h2",text:"How strong are they?"},{t:"p",text:"Against three Easy players, a Medium player won all 200 simulated games, and a Hard player won all 60. Among four Easy players, no seat had an advantage: the four seats won 95, 92, 107 and 106 of 400 games."},{t:"p",text:"In the arrangements the Hard search chose across 400 random hands, all four groups were a Pair or better every time. A random legal arrangement manages that in under 2% of hands."},{t:"h2",text:"What the model ignores"},{t:"ul",items:["It values a group by how it fares against random hands. It does not try to read what opponents hold.","It does not adjust for the score. A player who is far ahead or behind plays the same.","Nobody bluffs. Arrangements are hidden until the reveal, but there is no information to bluff with."]},{t:"p",text:"A deeper opponent could model other players' likely arrangements and choose a split to beat them. That is a harder problem with no obvious answer, and a good one for later."},{t:"h2",text:"Reproducible deals"},{t:"p",text:"Deals come from a seeded random number generator, so the app only needs to save a seed and the scores to rebuild the exact hands after a page reload. The pure game logic has its own unit tests, including a check that the points collected in any deal always add up to 360."},{t:"p",text:"You can [play against these opponents](/blog/play-hazari-against-the-computer/) in the scorekeeper."}]},{slug:"offline-first-scorekeeper-pwa",title:"Building an Offline-First Scorekeeper: IndexedDB, a Service Worker and No Backend",summary:"How a Hazari scorekeeper works with no connection: IndexedDB for games, a service worker for the app, validated backups and a deliberately small first download.",date:"2026-11-24",tags:["PWA","Offline First","IndexedDB","Dexie","React","TypeScript"],hub:"hazari",topic:"Behind the app",blocks:[{t:"p",text:"A card game scorekeeper has a hostile environment. It runs on a phone at a table, often on a poor connection, and it must never lose a score. That pushed the design toward one rule: scoring must never wait for a network."},{t:"h2",text:"Games live on the device"},{t:"p",text:"Saved games, rounds and recent player names are stored in the browser's IndexedDB through Dexie. There is no server for scoring and no account. The data layer is a small set of repository functions, and screens read through hooks and change data only through those functions, so storage can change without touching the interface."},{t:"h2",text:"A service worker keeps the app itself offline"},{t:"p",text:"A service worker caches the application shell, so it reloads with no connection after the first visit. The public guide pages are cached too, so they also work offline. A new version waits for the user to accept it, and it will not replace the app while a score draft is open."},{t:"h2",text:"Pure rules, separate from the screen"},{t:"p",text:"The scoring rules are a pure TypeScript module with its own unit tests. It knows nothing about React or IndexedDB. An architecture check in the build enforces this, so the domain code cannot import from the data or interface layers."},{t:"h2",text:"Validated backups"},{t:"p",text:"Players can export their games to a file and import them later. Anything that comes back in from a backup or a shared link is validated with Zod before it touches the database, so a damaged or hand-edited file cannot corrupt saved games."},{t:"h2",text:"Keeping the first download small"},{t:"p",text:"The app shell is about 98 KiB when compressed, under the 110 KiB limit I set for it. Anything heavy, such as the cloud sharing code and the QR generator, is loaded only when needed and is excluded from the first download and the offline cache. If those optional pieces fail to load, local scoring still works."},{t:"h2",text:"Privacy by construction"},{t:"p",text:"Game data stays on the device unless the user starts sharing. The site uses only basic pageview analytics, loaded in production only, with game links grouped and query strings removed. Names and scores are never sent, and there are no custom events."},{t:"p",text:"Settings includes a Clear device data option that asks for confirmation, offers an export first, and removes games, rounds and recent names together. The shared links that the device owned are closed separately, so clearing while offline cannot leave an old link alive."},{t:"h2",text:"How it is tested"},{t:"p",text:"Unit tests cover the rules. Browser tests cover the main flows at a 360 × 640 phone size, including offline use, five players, Bangla, and accessibility checks in light and dark themes."},{t:"p",text:"The overview of the whole app is in [How I built an offline Hazari scoring app](/blog/hazari-scoring-app/). The [live scoreboard design](/blog/read-only-live-scoreboard-design/) is the one part that does use a server."}]},{slug:"read-only-live-scoreboard-design",title:"Designing a Read-Only Live Scoreboard With Guest Sharing",summary:"How the Hazari scorekeeper shares a live scoreboard by link: opt-in guest sharing, an unguessable link, owner-only writes, expiry and revocation.",date:"2026-11-24",tags:["Firebase","Firestore","Security","Real-Time","Hazari"],hub:"hazari",topic:"Behind the app",blocks:[{t:"p",text:"The scorekeeper works fully offline, so live sharing had to be an add-on, not a requirement. The design goal was simple to say and tricky to build: friends can watch a game live from a link, they can never change it, and the scorer can switch it off."},{t:"h2",text:"Opt-in, and guest by default"},{t:"p",text:"Nothing is shared until the scorer taps Start sharing. Only then is an anonymous guest identity created, so local scoring and spectating never create one. Signing in with Google is optional, and linking Google keeps the same identity, so existing links are not orphaned."},{t:"h2",text:"The link is the key"},{t:"p",text:"Each shared scoreboard has a long random identifier, generated on the device. Anyone who has the link can watch and nobody can list scoreboards or guess one. The database rules deny listing and deny spectator writes, so viewing is the only thing a link allows."},{t:"h2",text:"One writer"},{t:"p",text:"Only the owner's identity can write or delete a shared scoreboard, and the rules bound the size and shape of what is written. The scorer's phone stays the source of truth: scoring is saved locally first, then published."},{t:"h2",text:"Publishing that does not slow scoring"},{t:"p",text:"Saved changes are batched into one snapshot and published in order. If a publish fails, it retries with growing delays up to 30 seconds, and a reconnect sends the newest state at once. A successful write counts as confirmed without an extra read. Scoring never waits for any of it."},{t:"h2",text:"Expiry and revocation"},{t:"ul",items:["Every link expires on its own, within 24 hours of creation.","Stopping sharing closes the link. If the scorer is offline, the closure is queued and completed when the app reconnects.","Clearing device data closes every link that device owned, so a reset cannot leave a live scoreboard behind.","A replacement is a new link, never a resurrection of the old one."]},{t:"h2",text:"One link for a whole session"},{t:"p",text:"When a game ends and the group plays again, the same link follows the new game, so viewers do not need a new link every time. They can also look back at the earlier games in the session."},{t:"h2",text:"What viewers never get"},{t:"p",text:"A viewer sees names, colours, rules and saved rounds. Drafts, recent names, other games and the scorer's Google profile are never in the shared data."},{t:"h2",text:"Testing it"},{t:"p",text:"The database rules are tested against a local emulator, along with browser tests covering two sessions at once, guest start, Google linking, reconnecting, expiry and revocation. Those tests use a demo project, never real game data."},{t:"p",text:"To use it, follow the guide on [sharing a Hazari scoreboard](/blog/share-hazari-scoreboard-live/). For the offline side of the app, see [how it works without a connection](/blog/offline-first-scorekeeper-pwa/)."}]},{slug:"bangla-card-names-hazari-app",title:"টেক্কা, সাহেব, বিবি, গোলাম: Making a Card Game App Natural in Bangla",summary:"How a Hazari app handles Bangla properly: real card names, suit names, hand names and typed translation keys, with a glossary of the terms used.",date:"2026-11-24",tags:["Bangla","Localization","Hazari","i18n","TypeScript"],hub:"hazari",topic:"Behind the app",blocks:[{t:"p",text:"Most card game apps treat Bangla as a translated afterthought. People who play Hazari in Bangladesh do not say King of Spades. They say ইস্কাপনের সাহেব. I wanted the scorekeeper to use the words players actually use."},{t:"h2",text:"A glossary of the terms"},{t:"ul",items:["**Ace:** টেক্কা","**King:** সাহেব","**Queen:** বিবি","**Jack:** গোলাম","**Spades:** ইস্কাপন","**Hearts:** হরতন","**Diamonds:** রুইতন","**Clubs:** চিড়িতন"]},{t:"p",text:"The hand names are written the way people say them: ট্রয় (Troy), কালার রান (Colour Run), রান (Run), কালার (Colour), পেয়ার (Pair) and ইন্ডি (Indi)."},{t:"h2",text:"Word order differs"},{t:"p",text:"English says “King of Spades”. Bangla puts the suit first, as in ইস্কাপন সাহেব. The translation for a card's spoken label is therefore a template with its own word order, not a joined pair of words. This matters for screen readers, which read that label."},{t:"h2",text:"Cards keep their faces"},{t:"p",text:"Printed cards keep the Latin letters and suit signs, like a real deck. The Bangla names appear in labels, hints and results. That keeps the cards recognisable while the interface around them is fully Bangla."},{t:"h2",text:"Typed translation keys"},{t:"p",text:"Every piece of interface text goes through a translation dictionary. The English dictionary defines the keys, and the Bangla dictionary is typed so it must provide every one of them. A missing Bangla string is a build error, not a blank space discovered later by a user."},{t:"h2",text:"Digits and banter"},{t:"ul",items:["An optional setting switches numbers to Bangla digits.","The funny leaderboard tags are written separately for Bangladesh, in Bangla, because jokes do not translate word for word."]},{t:"h2",text:"What I would still check"},{t:"p",text:"I wrote the Bangla for the app and the guides carefully, but native review matters, especially for jokes and for terms that differ between regions. If you spot a better word, tell me through the contact page."},{t:"p",text:"The Bangla leaderboard tags are covered in [roasting your friends at the table](/blog/hazari-banter-and-funny-tags/), and how the translated public pages are built is explained in [real HTML for a React app](/blog/real-html-for-a-react-app-seo/)."},{t:"p",text:"The Bangla guides on the app's site cover the rules and scoring: [হাজারী খেলার নিয়ম](https://hazari-card-game-scoring.vercel.app/bn/hazari-game-rules). The English version of this app's story is [here](/blog/hazari-scoring-app/)."}]},{slug:"real-html-for-a-react-app-seo",title:"Making a React App Findable: Real HTML Pages Before JavaScript Runs",summary:"How I made a React scorekeeper visible to search: real HTML guides generated at build time, private app routes marked noindex and structured data that matches the page.",date:"2026-11-24",tags:["SEO","React","Vite","Static Generation","Structured Data"],hub:"hazari",topic:"Behind the app",blocks:[{t:"p",text:"A scorekeeper is a React app, and a React app starts life as an empty page. Search engines can run JavaScript, but a page that is only a blank shell until scripts finish is slow to understand, and it tells readers nothing if scripts fail. So the public side of the Hazari scorekeeper is plain HTML."},{t:"h2",text:"Two kinds of page"},{t:"ul",items:["**Public pages:** the home page, guides on scoring, rules, card points and live sharing, plus About, Privacy and Contact, each in English and Bangla. They are real HTML before any JavaScript runs.","**App pages:** the saved games, scoring screens and shared scoreboards. They are private, marked noindex, and left out of the sitemap."]},{t:"h2",text:"Generated at build time"},{t:"p",text:"The public pages are written from translated source files by a build script, which also produces the robots file, the sitemap and the hosting configuration. Editing a guide means editing one source file and rebuilding. Public pages do not load React, the database, or the cloud code, and their initial JavaScript is held under a 15 KB limit by a build check."},{t:"h2",text:"Each page earns its place"},{t:"ul",items:["A unique title, description and H1.","Its own canonical address.","Reciprocal English and Bangla alternates so each language points to the other.","Social preview metadata.","Structured data that describes what is actually on the page. There are no invented reviews or ratings."]},{t:"h2",text:"Letting crawlers read the noindex"},{t:"p",text:"The robots file allows crawling. That sounds backwards, but a crawler can only obey a noindex instruction if it is allowed to fetch the page and read it. The sitemap lists only public pages, and never a game identifier or a shared link."},{t:"h2",text:"Checks that fail the build"},{t:"p",text:"The build verifies the content, metadata, language links, structured data hashes, sitemap, manifest and the JavaScript limit. Browser tests load every public page with JavaScript disabled, in both languages and both themes, and check that real content is there."},{t:"h2",text:"What it does not do"},{t:"p",text:"None of this guarantees a ranking. It removes technical obstacles and makes the pages honest and readable. The rest depends on whether people find the pages useful, and on time."},{t:"p",text:"This portfolio uses the same idea for its own pages. For the app itself, see [how it was built](/blog/hazari-scoring-app/), and for the offline engineering, [the offline-first notes](/blog/offline-first-scorekeeper-pwa/)."}]}],d=[{slug:"ai-coding-harness",title:"The AI Coding Harness I Reuse on Every Project (4 Files + Skills)",summary:"How I set up Claude Code and OpenCode before writing any code: 4 Markdown files plus the right skills. Copy the prompt, ship your MVP.",date:"2026-10-03",tags:["AI","Programming","Claude","Software Development","Productivity"],blogId:6,blocks:[{t:"p",text:"You spend an hour with an AI coding agent. It fixes the bug, refactors the module, and finds the real cause of the failing test."},{t:"p",text:"The next morning you open a new session and it knows none of it. It repeats the same dead end. It undoes a decision you made yesterday. You explain the project again from scratch."},{t:"p",text:"The model isn't the problem. The agent has nowhere to keep its work."},{t:"p",text:"So before I ask any agent to build a feature, I give it a place to keep it. Call it a harness: the instructions, memory, and skills wrapped around the model so its work survives between sessions. Mine is four plain Markdown files:"},{t:"p",text:"**`AGENTS.md`, `SESSION.md`, `CHECKLIST.md`, and `HANDOFF.md`.**"},{t:"p",text:"The most important one is **`SESSION.md`**. It works whether you use Claude Code, OpenCode, or another coding agent, and it takes about five minutes to set up."},{t:"p",text:"I came to this after years of building AI and AI-native software, including scalable services and systems. Working with frontier models such as Claude Opus taught me what an agent needs to record: what changed, what it learned, which issues are still open, and what the next agent needs to continue."},{t:"p",text:"These files hold the project's instructions and working state. Skills supply reusable procedures for planning, debugging, design, and verification. Together they give me a setup I can carry from project to project."},{t:"h2",text:"1. AGENTS.md: how I want the agent to work"},{t:"p",text:"This is where I put instructions that should outlive the current task:"},{t:"ul",items:["What the project does and how the code is organized.","Commands to run, build, and verify it.","Engineering conventions and important constraints.","When to read and update the other three files."]},{t:"p",text:"For a Python service, I include the boundaries between API handlers, business logic, and external services. I also make failure behavior explicit: what happens when a dependency times out, a request is invalid, or a background job fails?"},{t:"p",text:"A useful instruction to include is:"},{t:"note",text:"Before coding, read SESSION.md and CHECKLIST.md. After each meaningful change or investigation, update SESSION.md. Before finishing, review the checklist and prepare a handoff if work remains."},{t:"p",text:"**Use it for:** any repository you expect to revisit. Keep it short enough to read at the start of a session."},{t:"h2",text:"2. SESSION.md: the file that stops the forgetting"},{t:"p",text:"I want the reasoning and current state to stay with the project, not disappear when the chat closes."},{t:"p",text:"My session file captures **every meaningful change, its summary, findings, issues, and the review list**. An unsuccessful investigation belongs here too, because the next agent needs to know what was already tried."},{t:"p",text:"This is the structure I recommend:"},{t:"code",text:["# Session","","## Current objective","The outcome we are working toward now.","","## Changes","What changed, where, and why. Keep concise dated entries.","","## Findings and decisions","What we learned, the evidence, and the decision it informed.","","## Issues and review list","Open, resolved, or blocked issues; what still needs review.","","## Verification","Checks actually run and their results. Mark unrun checks clearly.","","## Next action","The next concrete step and any blocker."].join(`
`)},{t:"p",text:'For a document-processing MVP, an entry such as "fixed parsing" gives the next agent very little to work with. Record the failing input, the relevant parser, the change, and the check that confirmed it.'},{t:"p",text:"Keep the current objective and next action easy to find. Older entries can move to an archive as the log grows."},{t:"p",text:"**Use it for:** debugging, refactoring, research, service development, and anything that spans sessions. For a tiny task, a few lines are enough."},{t:"h2",text:'3. CHECKLIST.md: what "done" means'},{t:"p",text:'A checklist turns "build the MVP" into something you can review.'},{t:"p",text:"Each item needs an outcome and a way to confirm it. Here is an example for a document-processing app:"},{t:"code",text:["# MVP deliverables","","- [ ] Accept a supported document upload.","- [ ] Show extracted fields in an editable view.","- [ ] Explain unsupported-file and processing errors.","- [ ] Save a user's corrections.","- [ ] Verify the upload-to-result flow with a sample document.","- [ ] Document local setup and known limitations."].join(`
`)},{t:"p",text:"Creating a route or a component does not complete an item by itself. I want evidence that the intended behavior works. A blocked item stays visible with its reason."},{t:"p",text:"**Use it for:** MVPs, releases, client work, and features with several deliverables. For a bug fix, it can be just the reproduction, the fix, and a regression check."},{t:"h2",text:"4. HANDOFF.md: how any agent picks up the work"},{t:"p",text:"When I switch agents or pass work to a reviewer, I need a clear starting point."},{t:"p",text:"My handoff includes:"},{t:"ul",items:["The objective and current state.","Relevant files and decisions, with references to SESSION.md.","Remaining issues and verification gaps.","The next action and how to check its result."]},{t:"p",text:'An example handoff could say: "Upload validation is implemented. The browser flow still needs review. Start with the upload component, reproduce the unsupported-file case, and record the result in SESSION.md."'},{t:"p",text:"**Use it for:** another agent, another developer, a review, or a session you will resume later. Refresh it when transferring work; a short task completed in one sitting may not need it."},{t:"h2",text:"Which skills to add for which project"},{t:"p",text:"The four files are the foundation. Add skills according to the work in front of you."},{t:"p",text:"**Small script or focused bug fix:** Short instructions, a session note, and a completion checklist. Extra packs are optional."},{t:"p",text:"**Backend API or service:** The four-file structure plus one development workflow pack."},{t:"p",text:"**MVP with a user interface:** Add Frontend Design and Webapp Testing."},{t:"p",text:"**Dataset, model, or evaluation work:** Add the relevant Hugging Face skills."},{t:"p",text:"**Building an MCP server:** Add MCP Builder."},{t:"p",text:"**Long investigation or refactor:** Keep SESSION.md current. Add Planning with Files if its workflow helps manage the task."},{t:"p",text:"**Repeating your own engineering procedure:** Package that procedure with Skill Creator."},{t:"p",text:"Here is how I put those choices to work."},{t:"h3",text:"Backend work: choose one development workflow"},{t:"p",text:"I use [Superpowers](https://github.com/obra/superpowers) for structured planning, debugging, testing, and review. [Matt Pocock's skills](https://github.com/mattpocock/skills) are useful for clarifying a change and documenting decisions; the collection's `grill-with-docs` workflow fits that preparation."},{t:"p",text:"For an unclear feature, start with this instruction:"},{t:"note",text:"Clarify the expected behavior and failure cases. Record decisions in SESSION.md and turn the agreed scope into CHECKLIST.md before implementation."},{t:"p",text:"Pick one workflow to lead the task. For a backend-only MVP, this is where I start; design and ML packs can wait until the project needs them."},{t:"h3",text:"UI work: design it, then verify the interaction"},{t:"p",text:"I use [Frontend Design](https://github.com/anthropics/skills/tree/main/skills/frontend-design) to guide the interface and [Webapp Testing](https://github.com/anthropics/skills/tree/main/skills/webapp-testing) to inspect the local app with browser checks."},{t:"p",text:"Give the agent the main user journey: upload a document, correct a field, save it. Ask it to record screenshots, observed failures, and verification results against the checklist. Browser testing needs the required Playwright environment."},{t:"h3",text:"ML work: add only the relevant Hugging Face skills"},{t:"p",text:"[Hugging Face Skills](https://github.com/huggingface/skills) help with dataset, model, evaluation, and Hub workflows."},{t:"p",text:"I define the evaluation question first. For retrieval, that means deciding what a useful result looks like and which failure cases matter. Then I ask the agent to record dataset assumptions, commands, results, and unresolved findings in SESSION.md."},{t:"h3",text:"Agent tools: use MCP Builder when building the integration"},{t:"p",text:"I use [MCP Builder](https://github.com/anthropics/skills/tree/main/skills/mcp-builder) when exposing a service through an MCP server."},{t:"p",text:"Start with the tool's job, inputs, outputs, and failure behavior. Put the implementation and verification requirements in the checklist. The server and its connection still need to be configured and tested."},{t:"h3",text:"Longer work: give planning files one clear role"},{t:"p",text:"[Planning with Files](https://github.com/OthmanAdi/planning-with-files) provides persistent planning, findings, and progress workflows."},{t:"p",text:"It uses its own file conventions. If I add it, I decide which file owns each piece of state and link the records. Two competing progress logs make a handoff harder. My four-file setup already works without this pack; I add it when its workflow is useful."},{t:"h3",text:"Repeated work: turn your procedure into a skill"},{t:"p",text:"I use [Skill Creator](https://github.com/anthropics/skills/tree/main/skills/skill-creator) to make a recurring procedure reusable."},{t:"p",text:"A focused service-review skill could check validation, async behavior, timeouts, and dependency failures. Keep project-specific details in AGENTS.md and SESSION.md, so the procedure can travel to another repository."},{t:"h2",text:"The one prompt that starts your MVP"},{t:"p",text:"Copy this and fill in the brackets:"},{t:"code",text:["Build an MVP for [product] that helps [user] achieve [main outcome].","Use [stack]. The essential user journey is [steps].","For this version, exclude [out-of-scope features].","","Inspect the repository first. Preserve existing instructions and work.","Create or update these files before implementation:","","AGENTS.md — project structure, commands, conventions, and workflow.","SESSION.md — objective, change summaries, findings, decisions,","             every issue and its status, review list, verification,","             and next action.","CHECKLIST.md — MVP deliverables with acceptance criteria.","HANDOFF.md — current state, relevant files, remaining work,","             and instructions for the next agent.","","Use the available skills relevant to this project: [selected skills].","If a requested skill is unavailable, say so and continue with a","clear plan. Ask about missing information only when it blocks work.","Record other assumptions in SESSION.md.","","Build the smallest complete user journey first. After each meaningful","change or investigation, update SESSION.md. Verify deliverables with","appropriate checks; only mark checklist items complete with evidence.","Finish with run instructions, known gaps, and an updated handoff."].join(`
`)},{t:"p",text:"One prompt can start the build and set up the workflow. A working MVP still depends on a manageable scope, the environment, and checking the result. I keep reviewing and refining as the work develops."},{t:"p",text:"On the next project, reuse the structure and the relevant skills. Reset the session, checklist, and handoff, and adapt the project instructions. Old project state should not become the new project's context."},{t:"h2",text:"Does this work in Claude Code and OpenCode?"},{t:"p",text:"Yes, with a few checks."},{t:"p",text:"[OpenCode supports AGENTS.md](https://opencode.ai/docs/rules/). [Current Claude Code supports it too](https://code.claude.com/docs/en/memory), with version and configuration conditions. If Claude Code is loading CLAUDE.md instead, its documented `@AGENTS.md` import lets you share the instructions. Confirm which file your agent actually loads."},{t:"p",text:"The other three files are ordinary project documents. The prompt and AGENTS.md tell the agent to read and maintain them."},{t:"p",text:"Both tools support skill files, including project skills under `.claude/skills/`; see the [Claude Code](https://code.claude.com/docs/en/skills) and [OpenCode](https://opencode.ai/docs/skills/) documentation. Keep companion resources with a skill and follow each pack's installation instructions for your agent. Reusing the files does not guarantee that every plugin or runtime dependency transfers automatically."},{t:"h2",text:"Start tomorrow's session where today's ended"},{t:"p",text:"For your first project, start with a clear deliverable and a useful SESSION.md. Add the skill that helps with your next task."},{t:"p",text:"When you come back tomorrow, or hand the work to another agent, you should be able to see what happened and continue from there. That is the whole point of the four files."}]},{slug:"llm-in-production",title:"How to Use, Optimize, and Serve an LLM in Your Production System",summary:"A plain-English map of production LLM serving: making the model itself faster, building a serving system that holds P95/P99, and choosing an inference engine. Written as the overview to a three-part technical series.",date:"2026-06-20",tags:["LLM","Production Systems","Optimization","Inference","MLOps","vLLM"],externalLink:"https://medium.com/towards-artificial-intelligence/how-to-use-optimize-and-serve-an-llm-in-your-production-system-25fd40f63b6a",externalPlatform:"Medium",blogId:3,blocks:[{t:"p",text:"You shipped the demo. The model works. Stakeholders are happy. Then real traffic hits, and suddenly:"},{t:"ul",items:['"Why is the first response taking 3 seconds?"',`"We're burning $8,000/month on GPU bills — there has to be a better way."`,`"The model is fast in testing but crawls under load. What's going on?"`,'"We tried vLLM, TensorRT-LLM, and SGLang — which one do we actually use?"','"Our P99 latency is 4 seconds but P50 is fine. What does that even mean?"','"Can we fit a 70B model on two GPUs without destroying the quality?"','"Batch inference is killing our real-time users. How do we fix this?"']},{t:"p",text:"If any of these hit close to home, this article is the map. I also wrote a three-part technical series that goes an order of magnitude deeper on each section, from GPU kernels to cluster scaling. This is the territory; the series is the map you walk through it with."},{t:"h2",text:"Why this problem is harder than it looks"},{t:"p",text:"Deploying an LLM isn't like deploying a REST API. A Flask endpoint is stateless, horizontally scalable, and usually CPU-bound. An LLM inference server is none of those things."},{t:"p",text:"**1. Two completely different compute phases, back to back.** Every LLM request has two phases. The *prefill* phase reads your prompt — it's compute-intensive, runs fast, and can process many tokens in parallel. The *decode* phase generates the response one token at a time — it's memory-bandwidth-bound and inherently sequential. The bottleneck for each phase is a different hardware resource, so optimizing one without the other gets you half the gains."},{t:"p",text:"**2. The GPU's memory is both the product and the bottleneck.** The model weights live in GPU memory, and so does the KV cache — the stored attention state for every active request. These two fight each other. A 7B model in FP16 alone eats 14 GB of VRAM, so on a 40 GB A100 that leaves 26 GB for batching real users. How you manage that 26 GB decides whether you serve 4 concurrent users or 40."},{t:"p",text:"**3. Latency and throughput are opposites.** The things that make throughput high — large batches, long waits for requests to fill the batch — make latency worse. The things that make latency low waste GPU capacity. Production systems have to serve both interactive users who need sub-500ms responses and background jobs that need to process millions of documents cheaply. You can't use one configuration for both."},{t:"p",text:"**4. The ecosystem moves fast and breaks things.** vLLM, SGLang, TensorRT-LLM, and TGI have all had major changes in 2025 and 2026. What was best practice 12 months ago may be deprecated today — TGI, for example, was fully archived in March 2026, and if you're still building on it you need to migrate."},{t:"h2",text:"The three-layer mental model"},{t:"p",text:"Every production LLM problem lives in one of three layers. This is the organizing principle of the full series:"},{t:"code",text:`┌─────────────────────────────────────────────────────┐
│  Layer 3: ENGINE CHOICE                             │
│  Which inference runtime? vLLM, SGLang, TRT-LLM?   │
├─────────────────────────────────────────────────────┤
│  Layer 2: SERVING SYSTEM                            │
│  Queuing, traffic routing, autoscaling, SLAs        │
├─────────────────────────────────────────────────────┤
│  Layer 1: THE MODEL ITSELF                          │
│  Quantization, attention, GPU kernels, KV cache     │
└─────────────────────────────────────────────────────┘`},{t:"p",text:"Most engineers start at Layer 3 — picking an engine — and then discover their problems are actually in Layer 1 or 2. The right order is bottom-up: make the model efficient, then make the serving layer stable, then pick the engine that fits your workload."},{t:"h2",text:"Layer 1 — Making the model itself faster"},{t:"h3",text:"The core insight: decode is starving your GPU"},{t:"p",text:"Modern GPUs have hundreds of TFLOPS of tensor core capacity. But when generating tokens one by one, the GPU is mostly *reading weights from memory and doing almost no math on them*. Arithmetic intensity during decode is roughly 1 FLOP per byte of memory read; saturating tensor cores needs over 200 FLOP/byte. For most of a request's lifetime your expensive GPU sits idle at maybe 5–15% compute utilization, bottlenecked entirely on memory bandwidth."},{t:"p",text:"This is why quantization and caching work so well — they don't make the math faster, they reduce how much data the GPU has to haul across the memory bus per step."},{t:"h3",text:"The five-level optimization ladder"},{t:"p",text:"**Level 1 — BF16 + Flash Attention (free wins, zero quality loss).** Flash Attention rewrites the attention operation to avoid materializing the full N×N attention matrix in GPU memory. Instead of writing intermediate results back to slow HBM and reading them again, it fuses the operation into a single kernel that stays in fast on-chip SRAM. The result is 30–50% faster prefill on prompts longer than ~2K tokens with zero change to model quality. It's already on by default in vLLM and SGLang; if you're running anything else, check that it is."},{t:"p",text:"**Level 2 — INT8 quantization (1.5–2× batch size, negligible quality loss).** Storing weights as 8-bit integers instead of 16-bit floats halves memory use. Perplexity degradation is under 0.1% on standard benchmarks, which is essentially invisible, and you can fit twice the model — or twice as many concurrent users — into the same VRAM. Libraries like `bitsandbytes` make this close to a one-line change."},{t:"p",text:"**Level 3 — INT4 quantization / AWQ / GPTQ (3–4× memory, 2–3× throughput).** Going to 4-bit gives a 4× memory reduction; the challenge is doing it without quality collapse. Two methods are production-grade:"},{t:"ul",items:["**AWQ (Activation-Aware Weight Quantization)** identifies which weights actually matter by looking at activation magnitudes and protects them with higher precision. This is the recommended default for quality-sensitive deployments.","**GPTQ** uses a Hessian-based approach to minimize quantization error per layer. For inference speed, set `desc_act=False` — it's 2–3× faster at inference time with minimal quality trade-off."]},{t:"p",text:"Both are well-supported in vLLM and SGLang."},{t:"p",text:"**Level 4 — Paged KV cache + KV cache quantization (2–3× concurrency).** Without memory management the KV cache fragments — you might have 40% of your VRAM technically allocated but unusable because it sits in non-contiguous chunks. vLLM's PagedAttention solves this the way an OS solves memory fragmentation: by managing the cache in fixed-size pages of 16–64 tokens. GPU memory utilization typically improves from ~45% to ~85%."},{t:"p",text:"On top of that you can quantize the KV cache itself to FP8. The cost is ~5–10% throughput; the benefit is that the same VRAM holds twice as many active requests. At scale that trade is usually worth it."},{t:"p",text:"**Level 5 — Speculative decoding + tensor parallelism.** Speculative decoding uses a small draft model to predict several tokens ahead, then verifies them all at once with the main model. When predictions are mostly right — common phrases and patterns often are — you effectively generate multiple tokens per main-model forward pass, cutting TTFT and per-token latency by 2–3× on the right workloads. Tensor parallelism splits the model across GPUs, the standard approach for 70B+ models that don't fit on one card."},{t:"note",text:"Most teams stop at Level 3 and see TTFT drop from ~800ms to ~250ms with throughput improving from ~30 to ~80 tokens/second. Levels 4 and 5 are for teams with serious production scale."},{t:"h2",text:"Layer 2 — Building a serving system that doesn't fall apart under load"},{t:"h3",text:"The counterintuitive truth: your latency problem is probably queueing, not compute"},{t:"p",text:"Once a model is reasonably optimized, P95 and P99 latency are almost never caused by the GPU being slow. They're caused by *requests waiting*. A request that takes 50ms of actual GPU work can easily spend 800ms in queue because the batch scheduler waited for one more request, or because a 4K-token document summary monopolized the prefill slot while 12 chat queries waited."},{t:"h3",text:"The traffic lanes pattern"},{t:"p",text:"The single most impactful serving change most teams can make is also the simplest: **run interactive traffic and batch traffic on separate replicas.**"},{t:"p",text:"Interactive users — chat UI, streaming responses — need low time-to-first-token and can tolerate lower throughput. Batch jobs like document summarization and embedding pipelines need high throughput and can tolerate higher latency. These two workloads want opposite things from the scheduler, and forcing them to share a GPU means one will always suffer. vLLM lets you tune this per instance:"},{t:"code",text:`# Interactive lane: small batches, fast dispatch
--max-num-seqs 4

# Batch lane: large batches, maximum throughput
--max-num-seqs 16`},{t:"p",text:"Add short-prompt vs. long-prompt splitting and you've removed the most common source of P99 spikes in production."},{t:"h3",text:"Measure the right things"},{t:"p",text:'Most teams log "total request time," which is nearly useless for diagnosis. Log these instead, on every request:'},{t:"ul",items:["**TTFT (time-to-first-token)** — user-perceived responsiveness. This is the number users actually feel.","**TPOT (time per output token)** — decode speed, e.g. 20 ms/token. The inverse of tokens-per-second.","**Queue wait time** — how long the request waited before the GPU touched it. If this is high, your problem is the serving layer, not the model.","**Prefill time** — cost of reading the prompt. Spikes here mean long prompts or that Flash Attention is off.","**Decode time** — cost of generating the response. Spikes here mean quantization or batching issues.","**P95/P99 per traffic lane** — not a global P99, but per-lane: interactive vs. batch, short vs. long prompt."]},{t:"p",text:"Per-lane P99 matters especially. If you mix 50-token chat queries with 4K-token RAG summaries, a global P99 will always look terrible and will always be caused by the wrong thing."},{t:"h3",text:"Backpressure, admission control, graceful degradation"},{t:"p",text:'Production systems need a way to say "no" before they fall over:'},{t:"ul",items:["**Admission control** — return HTTP `429 Too Many Requests` (or `503`) when queue depth exceeds a threshold. Far better than letting requests queue for 30 seconds and then time out.","**Streaming backpressure** — if a client consumes tokens slowly, don't let it pin GPU memory indefinitely. Use a bounded async queue between the inference engine and the network layer.","**Cancel-on-disconnect** — if a user closes the browser tab, stop generating. Sounds obvious; most teams don't implement it."]},{t:"h3",text:"Cold start and autoscaling"},{t:"p",text:"LLM replicas are expensive to start. Weight loading, KV cache allocation, and warmup can add 30–90 seconds. During an autoscale event the new replica can't help for over a minute, and during that minute the remaining replicas absorb the full load spike. Two mitigations:"},{t:"ol",items:["Keep `minReplicaCount: 2` at all times. Never scale to zero for production models.","Scale on `vllm:num_requests_waiting` (queue depth), not CPU/GPU utilization. By the time utilization-based autoscaling triggers, users are already waiting."]},{t:"h2",text:"Layer 3 — Choosing the right inference engine"},{t:"ul",items:["**vLLM** — best for generalist production workloads, multi-LoRA, and broad model support. The default choice for most teams. Trade-off: not quite peak throughput on narrow, well-defined workloads.","**SGLang** — best for high-throughput APIs and shared-prefix workloads (RAG, few-shot prompting). Used at xAI and Microsoft Azure scale. Trade-off: multi-GPU ops less mature than TRT-LLM.","**TensorRT-LLM** — best for maximum raw throughput on NVIDIA hardware and latency-SLA-bound systems. Trade-off: requires compilation (~28 min for a 70B model) and a more complex setup.","**llama.cpp** — best for edge, local development, CPU, or Apple Silicon. Runs anywhere. Trade-off: not for production GPU serving at scale.","**LMDeploy** — near-SGLang throughput with simpler setup. Trade-off: smaller community and fewer integrations.","~~**TGI (Text Generation Inference)**~~ — fully archived on GitHub in March 2026. Read-only, no new development. If you're still building on TGI, migrate to vLLM or SGLang."]},{t:"h3",text:"The decision shortcuts"},{t:"ul",items:["**Starting fresh?** Use **vLLM**. Broadest model support, the most production documentation, and the default choice for most teams in 2026.","**Workload is primarily RAG or few-shot prompting** (many requests sharing a long system prompt or example set)? Use **SGLang**. Its RadixAttention automatically caches shared prefixes, giving roughly 29% higher throughput than vLLM on these workloads.","**Need the absolute lowest latency on NVIDIA hardware?** Compile with **TensorRT-LLM**. The ~28-minute compile for a 70B model is a one-time cost, and the runtime performance is the best available on NVIDIA GPUs.","**On the edge or local hardware?** **llama.cpp**. It runs on anything."]},{t:"h2",text:"The full picture — why all three layers matter together"},{t:"p",text:"Here's how the layers interact in a real scenario. Suppose you have a 7B model serving a chat application with 500 concurrent users:"},{t:"ol",items:["**Layer 1 (model optimization):** you apply AWQ INT4 quantization. The 14 GB FP16 model shrinks to ~4 GB, VRAM is freed for KV cache, and TTFT drops from 800ms to ~250ms.","**Layer 2 (serving system):** you split interactive and batch traffic into separate replicas, add admission control at depth > 20 requests, and configure KEDA to scale on `vllm:num_requests_waiting` with `minReplicaCount: 2`. P99 drops from 3.5 seconds to ~600ms.","**Layer 3 (engine choice):** you're using SGLang because your chat product has a long shared system prompt, so RadixAttention caches it automatically. Every request after the first skips re-computing 500 tokens of prefill, and throughput increases by ~29%."]},{t:"p",text:"None of these three layers alone gets you there. Model optimization means nothing if the queueing system serializes every request. Serving-system tuning means nothing if the model is eating all the VRAM. Engine choice means nothing if you haven't quantized."},{t:"h2",text:"TL;DR — the one-page cheat sheet"},{t:"ul",items:["**Slow first token (high TTFT)?** Layer 1 + Layer 2. Quantize to INT4/AWQ, split traffic lanes, add prefix caching.","**High GPU cost or low concurrency?** Layer 1. Quantize the model, enable paged KV cache, consider KV FP8 quantization.","**P99 much worse than P50?** Layer 2. Switch to per-lane metrics, add admission control (HTTP 429), implement cancel-on-disconnect.","**Crashing under load?** Layer 2. Add backpressure with a bounded queue, scale on queue depth rather than GPU utilization.","**Not sure which engine to use?** Layer 3. Start with vLLM. Move to SGLang if your workload is RAG or few-shot heavy. Use TRT-LLM only for hard latency SLAs on NVIDIA hardware.","**Model doesn't fit on one GPU?** Layer 1 + Layer 3. Quantize first — a 70B model at INT4 fits on two 40 GB A100s. Add tensor parallelism only if quantization isn't enough.","**Cold starts causing latency spikes?** Layer 2. Set `minReplicaCount: 2`, send warmup prompts on startup, and scale proactively on queue depth."]},{t:"note",text:"If this was useful, the three-part series goes an order of magnitude deeper on each section."}]},{slug:"hazari-scoring-app",title:"How I Built an Offline Hazari Scoring App Friends Can Watch Live",summary:"Why scoring Hazari on paper goes wrong, and how I built a free offline scorekeeper in English and Bangla with a read-only live scoreboard you share by link.",date:"2026-11-21",tags:["Hazari","Card Games","Progressive Web App","React","Offline First","Bangladesh"],blogId:7,hub:"hazari",topic:"Behind the app",blocks:[{t:"p",text:"Hazari is a card game that runs for many rounds. Every round, each player's points are added to a running total, and the first to reach the target wins. By default I use a target of 1000 and 360 points shared in each round."},{t:"p",text:"Keeping that score on paper or in a phone note is where the arguments start. A number is copied wrong, a round is added twice, and nobody can say who is really ahead. I built a scorekeeper to fix exactly that, and you can use it free at [hazari-card-game-scoring.vercel.app](https://hazari-card-game-scoring.vercel.app/)."},{t:"h2",text:"What the app does"},{t:"ul",items:["**Scores the game for you.** Enter each player's points for the round on a large keypad. The app adds the totals, ranks the players and shows how far each one is from the target.","**Works offline.** Once it has loaded, you can score with no connection. Games, rounds and recent player names are saved on your own device.","**English and Bangla.** The whole interface is available in both, with an optional switch to Bangla digits.","**Installs like an app.** It is a progressive web app, so you can add it to your phone's home screen.","**Lets friends watch live.** Start sharing and send a link. Everyone who opens it sees the leaderboard update as you save rounds, and no one else can change a score."]},{t:"h2",text:"Design choices that mattered"},{t:"h3",text:"A keypad you can use with one hand"},{t:"p",text:"Scoring happens at a table, often with a card in the other hand. So the keypad fills the remaining screen height, the buttons are at least 48 pixels, and the Next and Save buttons stay in a fixed place. There is a Fill button that completes the last player's score from what remains of the round total, and a one-tap Undo for a mistaken round."},{t:"h3",text:"A check that doesn't get in the way"},{t:"p",text:"A round should add up to the round total. When it doesn't, the app asks you to confirm before saving instead of blocking you, because house rules differ and sometimes the scorer knows better. Putting that choice in a dialog also means the keypad never moves while you type."},{t:"h3",text:"Rules kept apart from the interface"},{t:"p",text:"The scoring rules live in a small TypeScript module with its own unit tests, separate from the screens and the storage. That made it safe to change the interface many times without touching how points are counted."},{t:"h3",text:"Local first, then sharing"},{t:"p",text:"Scoring never needs an account or a server. Saved games live in the browser's IndexedDB. The only part that uses the cloud is live sharing, and it starts only when you choose to share. By default you share as a guest; signing in with Google is optional."},{t:"p",text:"A shared link is read-only and can be switched off. Viewers see a live leaderboard with who is leading and who deals next, plus small highlights such as a winning streak. The scorer's phone stays the single source of truth."},{t:"h3",text:"Playful tags"},{t:"p",text:"Because Hazari is a game among friends, the leaderboard teases players. Once two rounds are saved, each player gets a short tag based on their position, in English or Bangla, such as a boast for the leader and a friendly roast for whoever is last. The tag only changes when a new round is saved."},{t:"h2",text:"How it is built"},{t:"ul",items:["React 19 and TypeScript, built with Vite.","Dexie on IndexedDB for saved games, so scoring works without a network.","A service worker that caches the app, so it reloads offline.","Firebase only for the optional live scoreboard.","Zod to validate data that comes from backups and shared links.","Unit tests for the scoring rules and browser tests for the main flows, including offline use and accessibility."]},{t:"h2",text:"What it does not do"},{t:"p",text:"It is a scorekeeper first. A practice mode lets you play Hazari alone against three computer players, but it does not deal cards for a table of friends and there is no online multiplayer. Hazari rules also differ between regions, so the app follows a standard four-player rule set with an adjustable target and round total. If your table plays differently, change the numbers when you start a game."},{t:"h2",text:"Try it"},{t:"p",text:"Open the [Hazari scoring app](https://hazari-card-game-scoring.vercel.app/), start a game, and share the link with your table. The site also has short guides on [how to score Hazari](https://hazari-card-game-scoring.vercel.app/how-to-score-hazari) and the [rules of the game](https://hazari-card-game-scoring.vercel.app/hazari-game-rules), in English and Bangla."},{t:"p",text:"Want the details? See [how the computer opponent chooses its cards](/blog/how-the-hazari-computer-opponent-works/), the [design of the live scoreboard](/blog/read-only-live-scoreboard-design/) and the [offline-first notes](/blog/offline-first-scorekeeper-pwa/), or browse all the [Hazari guides](/hazari/)."},{t:"note",text:"More card-game scorekeepers may follow. If there is a game you would like scored this way, tell me through the contact page."}]}],s=[...d,...n,...i,...h,...l],m=a=>s.find(o=>o.slug===a),f=a=>s.filter(o=>o.hub===a),u="https://hazari-card-game-scoring.vercel.app/",c="https://hazari-card-game-scoring.vercel.app/play",y={heading:"Hazari card game guides",intro:"Hazari is a four-player card game played in South Asia. Each player arranges 13 cards into groups, the groups are compared, and the points add up to a running score until someone reaches 1,000. These pages explain the numbers, the strategy and the scoring, and show how the free scorekeeper behind them is built."},w=["Odds and numbers","Strategy","Scoring and house rules","Playing with friends","Behind the app"],t={heading:"Play it or score it",text:"Play Hazari alone against the computer, or keep score and share the banter with your friends. It is free and works offline.",play:{label:"Play against the computer",href:c},score:{label:"Keep score and share live",href:u}};function b(){return e.jsxs("section",{"aria-labelledby":"hazari-cta-heading",className:"mt-14 border border-primary/40 bg-primary/5 rounded-xl p-6 md:p-8",children:[e.jsx("h2",{id:"hazari-cta-heading",className:"text-2xl font-extrabold",children:t.heading}),e.jsx("p",{className:"mt-3 text-muted-foreground leading-relaxed max-w-[60ch]",children:t.text}),e.jsxs("div",{className:"mt-6 flex flex-wrap gap-3",children:[e.jsxs("a",{href:t.play.href,target:"_blank",rel:"noopener noreferrer",className:"btn-push inline-flex items-center gap-2 px-7 py-3.5 bg-primary text-primary-foreground rounded-full font-semibold text-sm",children:[t.play.label," ",e.jsx(r,{className:"w-4 h-4"})]}),e.jsxs("a",{href:t.score.href,target:"_blank",rel:"noopener noreferrer",className:"btn-push inline-flex items-center gap-2 px-7 py-3.5 border border-border rounded-full font-semibold text-sm",children:[t.score.label," ",e.jsx(r,{className:"w-4 h-4"})]})]})]})}export{b as H,m as a,s as b,w as c,y as d,f as h};
